"""Write docs/results.md from docs/results_rq1.json and docs/results_rq3.json (paper 3)."""
import json

l = json.load(open("docs/results_rq1.json"))
r = json.load(open("docs/results_rq3.json"))
pc = lambda v: f"{v*100:.1f}%"
ci = lambda c: f"{c['rate']*100:.1f}% ({c['ci95'][0]*100:.1f} to {c['ci95'][1]*100:.1f})"
o = ["# Paper 3 results", "",
     "Every number below is produced by the scripts named in each section; no number is typed by hand. "
     "Bootstrap seed 20261105, 2,000 resamples. Generated by `scripts/write_results.py`.", "",
     "## Runs", "",
     f"492 main runs were dispatched; {492 - len(r['not_reached'])} produced a scored record. Not reached (API error on every attempt): "
     + ", ".join(f"`{x}`" for x in r["not_reached"]) + ".", "",
     "Source: `data/runs/run_outcomes.jsonl`, built by `scripts/collect_runs.py` from the GitHub Actions artifacts of this repository.", "",
     "## Check claims (labeler against claims with labels known by construction)", ""]
g = l["check_claims"]
o += [f"Agreement: {g['agree']} of {g['n']} ({pc(g['share'])}).", "", "| Built-in label | Author's label | Claims |", "|---|---|---|"]
o += [f"| {k.split(' -> ')[0]} | {k.split(' -> ')[1]} | {n} |" for k, n in g["confusion"].items()]
o += ["", "## RQ1: labels of the 300 sampled claims", "",
      "Share of checkable claims (not checkable excluded, rubric v1 label 5), 95% cluster bootstrap interval over runs. "
      "Source: `scripts/analyze_labels.py` on the author's labels (sha256 6648a24388886b666d8ff34fd6604f94e0474f4460de7177f856db3652de28e4); "
      "the label file is published after the blind re-code of Nov 24, 2026.", "",
      "| Group | Claims | Checkable | Runs | Unsupported | Partly supported | Contradicted | Unsupported or contradicted |",
      "|---|---|---|---|---|---|---|---|"]
for sec in ("rq1_all", "rq1_by_condition", "rq1_by_model", "rq1_by_model_condition", "rq1_by_task"):
    for k, c in l[sec].items():
        o.append(f"| {k} | {c['claims']} | {c['checkable']} | {c['runs']} | {ci(c['unsupported'])} | {ci(c['partly_supported'])} | {ci(c['contradicted'])} | {ci(c['unsupported_or_contradicted'])} |")
e = l["exploratory_self_report"]
o += ["", f"Exploratory, not preregistered: {e['n']} sampled claims only report the agent's own submission or classification "
      f"(pattern `submitted|classified`; labels {e['labels']}). Without them:", "",
      "| Condition | Checkable | Unsupported | Partly supported | Contradicted | Unsupported or contradicted |", "|---|---|---|---|---|---|"]
for k, c in l["exploratory_rq1_without_self_report_by_condition"].items():
    o.append(f"| {k} | {c['checkable']} | {ci(c['unsupported'])} | {ci(c['partly_supported'])} | {ci(c['contradicted'])} | {ci(c['unsupported_or_contradicted'])} |")
o += ["", "## RQ3: root-cause accuracy, Condition B against Condition A", "",
      "Source: `scripts/analyze_runs.py`. Correct is the AIOpsLab evaluator's `success`. A problem is correct in a condition when at least 2 of its 3 runs are correct; a run not reached counts as not correct.", "",
      "| Model | Problems | Correct A | Correct B | Only A | Only B | Exact McNemar p | Holm p | B minus A (95% CI) |", "|---|---|---|---|---|---|---|---|---|"]
for m, v in r["rq3_mcnemar_primary"].items():
    o.append(f"| {m} | {v['problems']} | {v['correct_A']} | {v['correct_B']} | {v['only_A']} | {v['only_B']} | {v['p_exact']:.3f} | {v['p_holm']:.3f} | {v['diff_B_minus_A']*100:+.1f} pp ({v['diff_ci95'][0]*100:+.1f} to {v['diff_ci95'][1]*100:+.1f}) |")
o += ["", "Run-level accuracy, 95% bootstrap interval over problems:", "", "| Model and condition | Runs | Correct | Accuracy |", "|---|---|---|---|"]
for k, v in r["rq3_run_accuracy"].items():
    o.append(f"| {k} | {v['runs']} | {v['correct']} | {pc(v['accuracy'])} ({v['ci95'][0]*100:.1f} to {v['ci95'][1]*100:.1f}) |")
gm = r["rq3_glmm"]
o += ["", f"Secondary, random-intercept logistic regression over {gm['runs']} reached runs and {gm['problems']} problems (maximum likelihood, 30-point Gauss-Hermite quadrature): "
      f"condition B odds ratio {gm['condition_B']['odds_ratio']:.2f} (log-odds {gm['condition_B']['estimate']:.3f}, 95% CI {gm['condition_B']['ci95'][0]:.3f} to {gm['condition_B']['ci95'][1]:.3f}, Wald p {gm['condition_B']['p_wald']:.3f}); "
      f"Sonnet against Haiku odds ratio {gm['model_sonnet']['odds_ratio']:.2f} (Wald p {gm['model_sonnet']['p_wald']:.1e}); problem standard deviation {gm['sd_problem']:.2f} on the log-odds scale.", "",
      "## Secondary outcomes and Condition B format measures", "",
      "| Model and condition | Runs | Median steps | Median tokens | Median seconds to submit | Cost (USD) | Format failures | Parsed records with a rule violation | Links to items never exposed |",
      "|---|---|---|---|---|---|---|---|---|"]
for k, v in r["secondary"].items():
    if k.endswith("B"):
        ff = f"{v['format_failures']} of {v['runs']} ({pc(v['format_failure_rate'])})"
        rv = f"{v['records_with_rule_violation']} of {v['parsed_records']}"
        ln = f"{v['links_not_exposed']} of {v['evidence_links']} ({pc(v['share_links_not_exposed'])})"
    else:
        ff = rv = ln = "n/a"
    o.append(f"| {k} | {v['runs']} | {v['median_steps']:g} | {v['median_tokens']:,.0f} | {v['median_seconds_to_submit']:g} | {v['cost_usd']:.2f} | {ff} | {rv} | {ln} |")
o += ["", "A format failure is a Condition B run whose summary did not parse into a provenance record with at least one claim.", "",
      "## RQ2", "", "Not yet computed. It needs the link-recovery step of manuscript Section 4 for Condition A claims and the Stage 3 judge run on the 100 development and 200 test claims."]
open("docs/results.md", "w").write("\n".join(o) + "\n")
